function validate([startTime, endTime, profit]) {
  const n = startTime.length;
  if (n < 1 || n > 50000) return 'There must be 1 to 50000 jobs.';
  if (endTime.length !== n || profit.length !== n) return 'startTime, endTime and profit must have the same length.';
  for (let i = 0; i < n; i++) {
    if (!Number.isInteger(startTime[i]) || !Number.isInteger(endTime[i])) return 'Times are whole numbers.';
    if (startTime[i] < 1 || endTime[i] > 1000000000) return 'Times are between 1 and 10^9.';
    if (startTime[i] >= endTime[i]) return 'Each job must end after it starts.';
    if (!Number.isInteger(profit[i]) || profit[i] < 1 || profit[i] > 10000) return 'Each profit is between 1 and 10000.';
  }
  return null;
}

