function jobScheduling(startTime, endTime, profit) {
  const n = startTime.length;
  const jobs = startTime.map((start, i) => ({ start, end: endTime[i], gain: profit[i] }));
  jobs.sort((a, b) => a.end - b.end);
  const dp = new Array(n + 1).fill(0);

  for (let i = 1; i <= n; i++) {
    const job = jobs[i - 1];
    let left = 0;
    let right = i - 1;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (jobs[mid].end <= job.start) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    dp[i] = Math.max(dp[i - 1], dp[left] + job.gain);
  }
  return dp[n];
}

