function jobScheduling(startTime, endTime, profit) {
  // Jobs sorted by start; best[k] is the best profit using only jobs order[k..].
  const n = startTime.length;
  const order = [...Array(n).keys()].sort((a, b) => startTime[a] - startTime[b]);
  const best = new Array(n + 1).fill(0);
  for (let k = n - 1; k >= 0; k--) {
    const job = order[k];
    let next = k + 1;
    while (next < n && startTime[order[next]] < endTime[job]) next++;
    best[k] = Math.max(best[k + 1], profit[job] + best[next]);
  }
  return best[0];
}

