function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 9);
  // The time span varies so that some inputs are crowded with overlaps and others are sparse.
  const spans = large ? [100, 5000, 1000000, 999999999] : [4, 8, 15];
  const span = spans[Math.floor(rand() * spans.length)];
  const longest = large ? Math.max(2, Math.floor(span / 50)) : 5;
  const maxGain = large ? 10000 : 20;
  const startTime = [], endTime = [], profit = [];
  for (let i = 0; i < n; i++) {
    const start = 1 + Math.floor(rand() * span);
    const end = Math.min(1000000000, start + 1 + Math.floor(rand() * longest));
    startTime.push(start);
    endTime.push(end);
    profit.push(1 + Math.floor(rand() * maxGain));
  }
  return [startTime, endTime, profit];
}
